    with col0:
        if st.button("← Back", use_container_width=True, key=f"back_{domain['num']}_{step['id']}"):
            if idx == 0:
                st.session_state.substep_idx = -1  # back to this domain's overview
            else:
                st.session_state.substep_idx -= 1
            st.rerun()
    with col1:
        if st.button("✓ Mark complete", use_container_width=True, key=f"complete_{domain['num']}_{step['id']}"):
            st.session_state.completed.add(step["id"])
            st.rerun()
    with col2:
        is_last_substep = idx == len(SUBSTEPS) - 1
        label = "See it all come together →" if is_last_substep else "Next →"
        if st.button(label, use_container_width=True, type="primary", key=f"next_{domain['num']}_{step['id']}"):
            if is_last_substep:
                st.session_state.substep_idx = len(SUBSTEPS)  # recap page
            else:
                st.session_state.substep_idx += 1
            st.rerun()

    if step["id"] in st.session_state.completed:
        st.caption("✅ Completed")

